/*
 * WebGPU backend: programs. A program is a fragment shader module and one vertex shader module per vertex input
 * signature (WGSL needs to know which inputs have a buffer and their component type), generated by the core's WGSL
 * emitters (core/wgsl.h); a uniform block layout; and the pipeline layout (uniform bind group, texture bind group of
 * the stage texture types).
 */
#include "core/webgpu/wgpu_backend.h"
#include "core/shader.h"

namespace dxwebgl2 {

namespace {

inline WGPUStringView Label(const char *s) { return WGPUStringView{s, WGPU_STRLEN}; }

struct ScopeResult { bool done = false; WGPUErrorType type = WGPUErrorType_NoError; std::string message; };

} // namespace

WGPUShaderModule WebGPUBackend::CompileModule(const std::string &code, const char *label)
{
    WGPUShaderSourceWGSL src = WGPU_SHADER_SOURCE_WGSL_INIT;
    src.code = WGPUStringView{code.data(), code.size()};
    WGPUShaderModuleDescriptor md = WGPU_SHADER_MODULE_DESCRIPTOR_INIT;
    md.nextInChain = &src.chain;
    md.label = Label(label);
    // With dxwebgl2_SetDebug the compilation is checked right away (an error scope, waited for) and the source logged.
    const bool check = GetConfig().debug;
    if (check) wgpuDevicePushErrorScope(m_device, WGPUErrorFilter_Validation);
    WGPUShaderModule m = wgpuDeviceCreateShaderModule(m_device, &md);
    ++g_d3d.programsCreated;
    if (check)
    {
        ScopeResult r;
        WGPUPopErrorScopeCallbackInfo ci = WGPU_POP_ERROR_SCOPE_CALLBACK_INFO_INIT;
        ci.mode = WGPUCallbackMode_WaitAnyOnly;
        ci.callback = [](WGPUPopErrorScopeStatus, WGPUErrorType type, WGPUStringView message, void *ud, void *) {
            ScopeResult *res = static_cast<ScopeResult *>(ud);
            res->done = true;
            res->type = type;
            if (message.data) res->message.assign(message.data, message.length == WGPU_STRLEN ? strlen(message.data) : message.length);
        };
        ci.userdata1 = &r;
        if (WaitFuture(wgpuDevicePopErrorScope(m_device, ci)) && r.type != WGPUErrorType_NoError)
        {
            Log("WGSL %s module failed to compile: %s", label, r.message.c_str());
            Log("source:\n%s", code.c_str());
            DXW_HIT(Failed, "WGSL %s module failed to compile", label);
        }
    }
    return m;
}

WGPUBindGroupLayout WebGPUBackend::TextureLayout(uint32_t texSig)
{
    auto it = m_texLayouts.find(texSig);
    if (it != m_texLayouts.end()) return it->second;
    std::vector<WGPUBindGroupLayoutEntry> entries;
    for (int s = 0; s < MAX_STAGES; ++s)
    {
        const uint32_t type = (texSig >> (s * 2)) & 3;
        if (!type) continue;
        WGPUBindGroupLayoutEntry t = WGPU_BIND_GROUP_LAYOUT_ENTRY_INIT;
        t.binding = (uint32_t)s * 2;
        t.visibility = WGPUShaderStage_Fragment;
        t.texture.sampleType = WGPUTextureSampleType_Float;
        t.texture.viewDimension = type == 1 ? WGPUTextureViewDimension_2D : (type == 2 ? WGPUTextureViewDimension_Cube : WGPUTextureViewDimension_3D);
        entries.push_back(t);
        WGPUBindGroupLayoutEntry sm = WGPU_BIND_GROUP_LAYOUT_ENTRY_INIT;
        sm.binding = (uint32_t)s * 2 + 1;
        sm.visibility = WGPUShaderStage_Fragment;
        sm.sampler.type = WGPUSamplerBindingType_Filtering;
        entries.push_back(sm);
    }
    WGPUBindGroupLayoutDescriptor ld = WGPU_BIND_GROUP_LAYOUT_DESCRIPTOR_INIT;
    ld.entryCount = entries.size();
    ld.entries = entries.data();
    WGPUBindGroupLayout l = wgpuDeviceCreateBindGroupLayout(m_device, &ld);
    m_texLayouts[texSig] = l;
    return l;
}

/// The input signature the fixed-function vertex stage of `key` reads when every input is a float vector.
static uint32_t CanonicalSignature(const ProgramKey &key)
{
    uint32_t sig = WGSL_IN_FLOAT; // position
    if (key.hasNormal) sig |= WGSL_IN_FLOAT << (3 * 2);
    if (key.hasPSize) sig |= WGSL_IN_FLOAT << (4 * 2);
    if (key.hasDiffuse) sig |= WGSL_IN_FLOAT << (5 * 2);
    if (key.hasSpecular) sig |= WGSL_IN_FLOAT << (6 * 2);
    for (int i = 0; i < MAX_STAGES; ++i)
        if ((key.tcMask & (1u << i)) && key.stage[i].texGen == 0) sig |= WGSL_IN_FLOAT << ((7 + (key.stage[i].coordIndex & 7)) * 2);
    return sig;
}

Program *WebGPUBackend::CreateProgram(const ProgramKey &key, const VertexShaderObject *vso, const PixelShaderObject *pso)
{
    WGProgram *p = new WGProgram();
    p->key = key;
    p->uid = m_nextUid++;
    if (!m_device) return p;

    // The vertex stage is generated per input signature (VertexModule); the first one decides which uniforms the
    // program reads (the same for every signature).
    if (vso) p->vso = std::make_shared<VertexShaderObject>(*vso);
    const uint32_t sig = vso ? WgslSignatureOf(vso->layout) : CanonicalSignature(key);
    const WgslStage fs = pso ? GeneratePixelShaderWGSL(*pso, key) : GenerateFixedFunctionFragmentWGSL(key);
    const WgslStage vs = vso ? GenerateTranslatedVertexWGSL(*vso, key, sig) : GenerateFixedFunctionVertexWGSL(key, sig);
    if (fs.code.empty() || vs.code.empty()) return p; // invalid, remembered so that it is not retried every draw
    const uint32_t used = fs.usedUniforms | vs.usedUniforms;
    p->usedUniforms = used;
    for (int u = 0; u < U_COUNT; ++u)
        if (used & (1u << u)) p->usedGroups |= 1u << UniformGroupOf((UniformId)u);
    p->xfCount = vs.xfCount;
    p->layout = MakeWgslUniformLayout(used, key);
    p->block.assign(p->layout.blockSize, 0);
    p->fs = CompileModule(WgslModule(key, used, fs), pso ? "pixel shader" : "fixed-function fragment");
    p->vs.push_back({sig, CompileModule(WgslModule(key, used, vs), vso ? "vertex shader" : "fixed-function vertex")});

    for (int s = 0; s < key.stageCount; ++s)
        if (key.stage[s].texType) p->texSig |= (uint32_t)(key.stage[s].texType & 3) << (s * 2);
    WGPUBindGroupLayout layouts[2] = {m_uniformLayout, nullptr};
    if (p->texSig) layouts[1] = p->texLayout = TextureLayout(p->texSig);
    WGPUPipelineLayoutDescriptor pld = WGPU_PIPELINE_LAYOUT_DESCRIPTOR_INIT;
    pld.bindGroupLayoutCount = p->texSig ? 2 : 1;
    pld.bindGroupLayouts = layouts;
    p->pipelineLayout = wgpuDeviceCreatePipelineLayout(m_device, &pld);
    p->valid = true;
    return p;
}

WGPUShaderModule WebGPUBackend::VertexModule(WGProgram *p, uint32_t signature)
{
    for (const WGVertexVariant &v : p->vs)
        if (v.signature == signature) return v.module;
    const WgslStage vs = p->vso ? GenerateTranslatedVertexWGSL(*p->vso, p->key, signature) : GenerateFixedFunctionVertexWGSL(p->key, signature);
    WGPUShaderModule m = CompileModule(WgslModule(p->key, p->usedUniforms, vs), p->vso ? "vertex shader" : "fixed-function vertex");
    p->vs.push_back({signature, m});
    return m;
}

void WebGPUBackend::DestroyProgram(Program *program)
{
    WGProgram *p = static_cast<WGProgram *>(program);
    if (!p) return;
    // Its pipelines go with it.
    for (auto it = m_pipelines.begin(); it != m_pipelines.end();)
    {
        auto &list = it->second;
        for (size_t i = 0; i < list.size();)
        {
            if (list[i].first.program == p->uid)
            {
                if (m_lastPipeline == list[i].second) m_lastPipeline = nullptr;
                if (m_curPipeline == list[i].second) m_curPipeline = nullptr;
                wgpuRenderPipelineRelease(list[i].second);
                list[i] = list.back();
                list.pop_back();
            }
            else ++i;
        }
        it = list.empty() ? m_pipelines.erase(it) : std::next(it);
    }
    if (p->fs) wgpuShaderModuleRelease(p->fs);
    for (WGVertexVariant &v : p->vs) wgpuShaderModuleRelease(v.module);
    if (p->pipelineLayout) wgpuPipelineLayoutRelease(p->pipelineLayout);
    delete p;
}

//------------------------------------------------------------------------------
// Uniforms
//------------------------------------------------------------------------------
/// Brings the CPU copy of the program's uniform block up to date: only the groups some uniform of the program belongs
/// to, and only when a state of the group changed since the program last received it.
void WebGPUBackend::UploadUniforms(WGProgram *p, const uint32_t *versions, UniformSource &source)
{
    uint32_t pending = 0;
    for (int g = 0; g < G_COUNT; ++g)
        if ((p->usedGroups & (1u << g)) && p->ver[g] != versions[g]) pending |= 1u << g;
    if (!pending) return;
    m_sinkProgram = p;
    for (int g = 0; g < G_COUNT; ++g)
    {
        if (!(pending & (1u << g))) continue;
        p->ver[g] = versions[g];
        ++g_d3d.uniformUploads;
        ++g_d3d.groupUploads[g];
        source.WriteUniforms((UniformGroup)g, *p, *this);
    }
    p->blockDirty = true;
}

void WebGPUBackend::Vec4(UniformId u, const float *v, int count)
{
    const WgslUniformLayout &l = m_sinkProgram->layout;
    if (l.offset[u] == UINT16_MAX) return;
    memcpy(m_sinkProgram->block.data() + l.offset[u], v, Min<size_t>((size_t)count * 16, l.size[u]));
}

void WebGPUBackend::Vec2(UniformId u, const float *v, int count)
{
    const WgslUniformLayout &l = m_sinkProgram->layout;
    if (l.offset[u] == UINT16_MAX) return;
    for (int i = 0; i < count && (uint32_t)(i + 1) * 16 <= l.size[u]; ++i)
        memcpy(m_sinkProgram->block.data() + l.offset[u] + i * 16, v + i * 2, 8);
}

void WebGPUBackend::Float(UniformId u, const float *v, int count)
{
    const WgslUniformLayout &l = m_sinkProgram->layout;
    if (l.offset[u] == UINT16_MAX) return;
    memcpy(m_sinkProgram->block.data() + l.offset[u], v, Min<size_t>((size_t)count * 4, l.size[u]));
}

void WebGPUBackend::Mat4(UniformId u, const float *m, int count)
{
    const WgslUniformLayout &l = m_sinkProgram->layout;
    if (l.offset[u] == UINT16_MAX) return;
    memcpy(m_sinkProgram->block.data() + l.offset[u], m, Min<size_t>((size_t)count * 64, l.size[u]));
}

} // namespace dxwebgl2
